function readProfileSection(section) {
  const clean = value => String(value ?? "").replace(/\s+/g, " ").trim();
  const text = el => {
    if (!el) return "";
    const copy = el.cloneNode(true);
    copy.querySelectorAll("i").forEach(n => n.remove());
    return clean(copy.textContent);
  };
  const root = document.querySelector("main #" + section);
  const profile = document.querySelector("main .profil-header .btn-share[data-url]");
  const profileUrl = profile?.getAttribute("data-url") ?? "";
  if (!root) return { section, profileUrl, ready: false, rows: [], displayed: null, total: null };
  const visible = root.getClientRects().length > 0 && getComputedStyle(root).display !== "none";
  const counterText = text(root.querySelector(".filters > .chip"));
  const counter = counterText.replace(/\s/g, "").match(/^(\d+)(?:\/(\d+))?$/);
  const displayed = counter ? Number(counter[1]) : null;
  const total = counter ? Number(counter[2] ?? counter[1]) : null;
  const rows = [...root.querySelectorAll(".game")].map(card => {
    const link = card.querySelector('.title a[href*="#!/game/"]') || card.querySelector('.picture a[href*="#!/game/"]');
    if (!link) throw new Error("Carte sans lien MyLudo dans " + section);
    const href = link.getAttribute("href");
    const id = href.match(/-(\d+)(?:\/|$)/)?.[1];
    if (!id) throw new Error("Identifiant de jeu introuvable : " + href);
    const title = text(link) || clean(link.getAttribute("title"));
    const subtitle = text(card.querySelector(".subtitle"));
    const label = text(card.querySelector(".status"));
    if (!title) throw new Error("Nom de jeu manquant : " + id);
    return {
      id,
      url: "https://www.myludo.fr/" + href,
      Nom: subtitle && !title.toLowerCase().includes(subtitle.toLowerCase()) ? title + " - " + subtitle : title,
      statuts: section,
      edition_label: label,
      price_label: section === "wishlist" ? text(card.querySelector("p.context")) : null
    };
  });
  const filters = root.querySelector("#filter-panel");
  const words = filters?.querySelector('input[name="words"]')?.value ?? "";
  const groups = filters ? [...filters.querySelectorAll(".btn-group[data-name]")].map(g => ({
    name: g.getAttribute("data-name"), value: g.getAttribute("data-value") ?? ""
  })) : [];
  return {
    section, profileUrl, ready: visible && counter !== null, displayed, total, counterText,
    rows, hasFull: !!root.querySelector("a.full"), hasMore: !!root.querySelector("a.more"),
    words, filterGroups: groups
  };
}

