async function openProfileSection(page, config, section, resetFilters) {
  // A fresh document avoids hash-route reuse and stale hidden tabs.
  await page.goto("about:blank");
  const response = await page.goto("https://www.myludo.fr/#!/profil/" + config.profile + "/" + section, { waitUntil: "domcontentloaded" });
  if (response && response.status() >= 400) throw new Error(section + " : HTTP " + response.status());
  await page.waitForFunction(({ section, profileId }) => {
    const share = document.querySelector("main .profil-header .btn-share[data-url]");
    return share?.getAttribute("data-url")?.endsWith("-" + profileId)
      && !!document.querySelector('main .tabs a[href="#' + section + '"]');
  }, { timeout: 18000 }, { section, profileId: config.profileId });
  await page.evaluate(section => {
    const tab = document.querySelector('main .tabs a[href="#' + section + '"]');
    const root = document.querySelector("main #" + section);
    if (tab && (!root || !root.getClientRects().length || getComputedStyle(root).display === "none" || !tab.classList.contains("active"))) tab.click();
  }, section);
  const waitReady = async () => {
    await page.waitForFunction(section => {
      const root = document.querySelector("main #" + section);
      const chip = root?.querySelector(".filters > .chip")?.cloneNode(true);
      if (!root || !chip || !root.getClientRects().length || getComputedStyle(root).display === "none") return false;
      chip.querySelectorAll("i").forEach(el => el.remove());
      return /^\d+(?:\/\d+)?$/.test(chip.textContent.replace(/\s/g, ""));
    }, { timeout: 18000 }, section);
  };
  await waitReady();
  if (resetFilters) {
    await page.evaluate(section => document.querySelector("main #" + section + " .btn-clear-filters")?.click(), section);
    // MyLudo refreshes this tab asynchronously after clearing its filters.
    await new Promise(resolve => setTimeout(resolve, 700));
    await waitReady();
  }
  const state = await page.evaluate(readProfileSection, section);
  if (!state.ready || !state.profileUrl.endsWith("-" + config.profileId)) throw new Error(section + " : accès au profil non confirmé");
  return state;
}

export default async function checkAccess({ page, context = {} }) {
  try {
    const config = await prepareBrowser(page, context);
    const sections = [];
    for (const section of ["collection", "wishlist"]) {
      const state = await openProfileSection(page, config, section, false);
      sections.push({ section, accessible: true, total: state.total });
    }
    return { data: { ok: true, statut_session: "valide", mode_acces: config.cookies?.length ? "avec_cookies" : "public", sections }, type: "application/json" };
  } catch (error) {
    return { data: { ok: false, statut_session: "inaccessible", erreur: "MyLudo : " + error.message + ". Vérifier la visibilité du profil, la connexion éventuelle et la disponibilité du site." }, type: "application/json" };
  }
}

