// ============================================================
// BROWSER
// ============================================================

async function prepareBrowser(
  page,
  rawContext
) {
  const context =
    typeof rawContext ===
    "string"
      ? JSON.parse(
          rawContext
        )
      : (
          rawContext ??
          {}
        );

  const profile =
    context.profile ??
    "ludomaster-139495";

  const profileId =
    profile.match(
      /-(\\d+)$/
    )?.[1];

  if (
    !profileId ||
    !/^[a-z0-9-]+$/i.test(
      profile
    )
  ) {
    throw new Error(
      "Profil MyLudo invalide"
    );
  }

  page.setDefaultNavigationTimeout(
    20000
  );

  page.setDefaultTimeout(
    18000
  );

  await page.setViewport({
    width: 1365,
    height: 1000
  });

  await page.setRequestInterception(
    true
  );

  page.on(
    "request",
    request => {
      const action =
        [
          "image",
          "font",
          "media"
        ].includes(
          request.resourceType()
        )
          ? request.abort()
          : request.continue();

      action.catch(
        () => {}
      );
    }
  );

  if (
    Array.isArray(
      context.cookies
    ) &&
    context.cookies.length
  ) {
    const cookies =
      context.cookies.map(
        cookie => {
          const domain =
            String(
              cookie.domain ??
              "www.myludo.fr"
            ).replace(
              /^\\./,
              ""
            );

          if (
            domain !==
              "myludo.fr" &&
            !domain.endsWith(
              ".myludo.fr"
            )
          ) {
            throw new Error(
              "Cookie hors du domaine MyLudo"
            );
          }

          return {
            ...cookie,

            domain:
              cookie.domain ??
              ".myludo.fr",

            path:
              cookie.path ??
              "/"
          };
        }
      );

    await page.setCookie(
      ...cookies
    );
  }

  return {
    ...context,
    profile,
    profileId
  };
}


// ============================================================
// OPEN SECTION
// ============================================================

async function openProfileSection(
  page,
  config,
  section,
  resetFilters
) {
  await page.goto(
    "about:blank"
  );

  const response =
    await page.goto(
      "https://www.myludo.fr/#!/profil/" +
        config.profile +
        "/" +
        section,

      {
        waitUntil:
          "domcontentloaded"
      }
    );

  if (
    response &&
    response.status() >=
      400
  ) {
    throw new Error(
      section +
      " : HTTP " +
      response.status()
    );
  }

  try {
    await page.waitForFunction(
      ({
        section,
        profileId
      }) => {
        const share =
          document.querySelector(
            "main .profil-header .btn-share[data-url]"
          );

        return (
          share
            ?.getAttribute(
              "data-url"
            )
            ?.endsWith(
              "-" +
              profileId
            ) &&
          !!document.querySelector(
            'main .tabs a[href="#' +
              section +
              '"]'
          )
        );
      },

      {
        timeout: 18000
      },

      {
        section,
        profileId:
          config.profileId
      }
    );
  } catch {
    throw new Error(
      section +
      " : profil/onglet non chargé"
    );
  }

  await page.evaluate(
    section => {
      const tab =
        document.querySelector(
          'main .tabs a[href="#' +
            section +
            '"]'
        );

      const root =
        document.querySelector(
          "main #" +
          section
        );

      if (
        tab &&
        (
          !root ||
          !root
            .getClientRects()
            .length ||
          getComputedStyle(
            root
          ).display ===
            "none" ||
          !tab.classList.contains(
            "active"
          )
        )
      ) {
        tab.click();
      }
    },

    section
  );

  const waitReady =
    async label => {
      try {
        await page.waitForFunction(
          section => {
            const root =
              document.querySelector(
                "main #" +
                section
              );

            const chip =
              root
                ?.querySelector(
                  ".filters > .chip"
                )
                ?.cloneNode(
                  true
                );

            if (
              !root ||
              !chip ||
              !root
                .getClientRects()
                .length ||
              getComputedStyle(
                root
              ).display ===
                "none"
            ) {
              return false;
            }

            chip
              .querySelectorAll(
                "i"
              )
              .forEach(
                el =>
                  el.remove()
              );

            return /^\\d+(?:\\/\\d+)?$/.test(
              chip.textContent.replace(
                /\\s/g,
                ""
              )
            );
          },

          {
            timeout: 18000
          },

          section
        );
      } catch {
        throw new Error(
          section +
          " : compteur non prêt (" +
          label +
          ")"
        );
      }
    };

  await waitReady(
    "ouverture"
  );

  if (resetFilters) {
    await page.evaluate(
      section =>
        document
          .querySelector(
            "main #" +
            section +
            " .btn-clear-filters"
          )
          ?.click(),

      section
    );

    await new Promise(
      resolve =>
        setTimeout(
          resolve,
          700
        )
    );

    await waitReady(
      "après suppression des filtres"
    );
  }

  const state =
    await page.evaluate(
      readProfileSection,
      section
    );

  if (
    !state.ready ||
    !state.profileUrl.endsWith(
      "-" +
      config.profileId
    )
  ) {
    throw new Error(
      section +
      " : accès au profil non confirmé"
    );
  }

  return state;
}


