async function loadEntireSection(
  page,
  config,
  section
) {
  let state =
    await openProfileSection(
      page,
      config,
      section,
      true
    );

  if (
    state.words ||
    state.filterGroups.some(
      g =>
        g.name ===
          "filter" &&
        g.value
    )
  ) {
    throw new Error(
      section +
      " : filtre encore actif"
    );
  }

  let clicks = 0;

  while (
    state.rows.length !==
    state.total
  ) {
    if (
      state.rows.length >
        state.total ||
      clicks >= 20
    ) {
      throw new Error(
        section +
        " : compteur incohérent ou pagination incomplète"
      );
    }

    const previousCount =
      state.rows.length;

    const clicked =
      await page.evaluate(
        section => {
          const root =
            document.querySelector(
              "main #" +
              section
            );

          const button =
            root
              ?.querySelector(
                "a.full"
              ) ||
            root
              ?.querySelector(
                "a.more"
              );

          if (!button) {
            return false;
          }

          button.click();

          return true;
        },

        section
      );

    if (!clicked) {
      throw new Error(
        section +
        " : bouton Tout/Plus absent, " +
        previousCount +
        "/" +
        state.total
      );
    }

    try {
      await page.waitForFunction(
        ({
          section,
          previousCount
        }) => {
          const root =
            document.querySelector(
              "main #" +
              section
            );

          return (
            root &&
            root.querySelectorAll(
              ".game"
            ).length >
              previousCount
          );
        },

        {
          timeout: 20000
        },

        {
          section,
          previousCount
        }
      );
    } catch {
      throw new Error(
        section +
        " : aucun nouveau jeu après clic Tout/Plus (" +
        previousCount +
        "/" +
        state.total +
        ")"
      );
    }

    state =
      await page.evaluate(
        readProfileSection,
        section
      );

    if (!state.ready) {
      throw new Error(
        section +
        " : liste disparue pendant le chargement"
      );
    }

    clicks++;
  }

  await new Promise(
    resolve =>
      setTimeout(
        resolve,
        500
      )
  );

  state =
    await page.evaluate(
      readProfileSection,
      section
    );

  if (
    !state.ready ||
    state.rows.length !==
      state.total ||
    state.displayed !==
      state.total
  ) {
    throw new Error(
      section +
      " : extraction partielle (" +
      state.rows.length +
      "/" +
      state.total +
      ")"
    );
  }

  const ids =
    new Set(
      state.rows.map(
        row => row.id
      )
    );

  if (
    ids.size !==
    state.rows.length
  ) {
    throw new Error(
      section +
      " : identifiants répétés dans la liste"
    );
  }

  return {
    section,

    total:
      state.total,

    count:
      state.rows.length,

    complete:
      true,

    rows:
      state.rows
  };
}


