async function readPublicStats(
  page
) {
  return await page.evaluate(
    () => {
      const clean = value =>
        String(value ?? "")
          .replace(
            /\\s+/g,
            " "
          )
          .trim();

      const normalize = value =>
        clean(value)
          .normalize(
            "NFD"
          )
          .replace(
            /[\\u0300-\\u036f]/g,
            ""
          )
          .toLowerCase();

      const text = el => {
        if (!el) {
          return "";
        }

        const copy =
          el.cloneNode(
            true
          );

        copy
          .querySelectorAll(
            "i"
          )
          .forEach(
            n =>
              n.remove()
          );

        return clean(
          copy.textContent
        );
      };

      const toInteger =
        value => {
          const match =
            clean(value)
              .replace(
                /[\\s\\u00a0\\u202f]/g,
                ""
              )
              .match(
                /-?\\d+/
              );

          return match
            ? Number(
                match[0]
              )
            : null;
        };

      const root =
        document.querySelector(
          "main #stats"
        );

      if (!root) {
        return {
          ready:
            false,

          reason:
            "#stats absent",

          duration:
            null,

          parties:
            null,

          details:
            null,

          top10:
            []
        };
      }

      const cards = [
        ...root.querySelectorAll(
          ".card-content"
        )
      ];

      const findCard =
        heading =>
          cards.find(
            card =>
              normalize(
                text(
                  card.querySelector(
                    "h6"
                  )
                )
              ) ===
              normalize(
                heading
              )
          ) ?? null;

      const readStats =
        (
          card,
          selector
        ) => {
          const values = {};

          if (!card) {
            return values;
          }

          for (
            const container
            of card.querySelectorAll(
              ".stat-container"
            )
          ) {
            const label =
              normalize(
                text(
                  container.querySelector(
                    selector
                  )
                )
              );

            const value =
              toInteger(
                text(
                  container.querySelector(
                    ".stat-number"
                  )
                )
              );

            if (
              label &&
              value !== null
            ) {
              values[label] =
                value;
            }
          }

          return values;
        };


      // ========================================================
      // TOTAL PLAY TIME
      // ========================================================

      const durationValues =
        readStats(
          findCard(
            "Durée totale de jeu"
          ),
          ".stat-detail"
        );

      const duration = {
        years:
          durationValues.annees ??
          null,

        months:
          durationValues.mois ??
          null,

        days:
          durationValues.jours ??
          null,

        hours:
          durationValues.heures ??
          null,

        minutes:
          durationValues.minutes ??
          null
      };


      // ========================================================
      // PARTIES
      // ========================================================

      const partyValues =
        readStats(
          findCard(
            "Parties"
          ),
          ".stat-label"
        );

      const parties = {
        total:
          partyValues.total ??
          null,

        cooperation:
          partyValues.cooperation ??
          null,

        solo:
          partyValues.solo ??
          null
      };


      // ========================================================
      // DETAILS
      // ========================================================

      const detailValues =
        readStats(
          findCard(
            "Détails"
          ),
          ".stat-label"
        );

      const details = {
        games:
          detailValues.jeux ??
          null,

        places:
          detailValues.lieux ??
          null,

        h_index:
          detailValues[
            "h-index"
          ] ??
          null
      };


      // ========================================================
      // TOP 10
      // ========================================================

      const rankingTable = [
        ...root.querySelectorAll(
          "table.ranking-table"
        )
      ].find(
        table =>
          normalize(
            text(
              table.querySelector(
                "thead"
              )
            )
          ).includes(
            "top 10 jeu"
          )
      );

      const top10 =
        rankingTable
          ? [
              ...rankingTable
                .querySelectorAll(
                  "tbody tr"
                )
            ]
              .map(
                (
                  row,
                  index
                ) => {
                  const cells = [
                    ...row.querySelectorAll(
                      "td"
                    )
                  ];

                  const link =
                    cells[0]
                      ?.querySelector(
                        'a[href*="#!/game/"]'
                      );

                  if (!link) {
                    return null;
                  }

                  const href =
                    link.getAttribute(
                      "href"
                    ) ?? "";

                  const titleCopy =
                    link.cloneNode(
                      true
                    );

                  titleCopy
                    .querySelectorAll(
                      ".rank"
                    )
                    .forEach(
                      el =>
                        el.remove()
                    );

                  return {
                    rank:
                      toInteger(
                        text(
                          link.querySelector(
                            ".rank"
                          )
                        )
                      ) ??
                      index + 1,

                    id:
                      href.match(
                        /-(\\d+)\\/stats(?:$|[?#])/
                      )?.[1] ??
                      href.match(
                        /-(\\d+)(?:\\/|$)/
                      )?.[1] ??
                      null,

                    name:
                      text(
                        titleCopy
                      ),

                    duration_minutes:
                      toInteger(
                        text(
                          cells[1]
                        )
                      ) ??
                      0,

                    plays:
                      toInteger(
                        text(
                          cells[2]
                        )
                      ) ??
                      0,

                    url:
                      href.startsWith(
                        "http"
                      )
                        ? href
                        : "https://www.myludo.fr/" +
                          href
                  };
                }
              )
              .filter(
                Boolean
              )
          : [];

      const ready =
        Object
          .values(
            duration
          )
          .every(
            Number.isInteger
          ) &&
        Object
          .values(
            parties
          )
          .every(
            Number.isInteger
          ) &&
        Object
          .values(
            details
          )
          .every(
            Number.isInteger
          );

      return {
        ready,
        duration,
        parties,
        details,
        top10
      };
    }
  );
}


