function unwrapResponse(value) {
  let current = value;

  for (let i = 0; i < 4; i++) {
    if (typeof current === "string") {
      try {
        current = JSON.parse(current);
      } catch {
        throw new Error("Réponse Browserless non JSON");
      }
    } else if (
      current &&
      typeof current === "object" &&
      "data" in current &&
      !("ok" in current)
    ) {
      current = current.data;
    } else {
      break;
    }
  }

  if (
    !current ||
    typeof current !== "object" ||
    Array.isArray(current)
  ) {
    throw new Error(
      "Réponse Browserless vide ou invalide"
    );
  }

  if (
    current.error ||
    current.erreur ||
    current.ok === false
