function parseEuro(raw) {
  if (
    raw === null ||
    raw === undefined ||
    String(raw).trim() === ""
  ) {
    return null;
  }

  const text =
    String(raw).trim();

  // Explicitly free items have a known price of zero.
  if (/^gratuite?s?$/i.test(text)) {
    return 0;
  }

  // Missing prices remain unknown.
  if (
    /^(?:[-–—?]|n\/a|nc|n\.c\.|non renseign[eé]|indisponible)$/i.test(
      text
    )
  ) {
    return null;
  }

  const compact =
    text
      .replace(
        /[\s\u00a0\u202f]/g,
        ""
      )
      .replace(
        /(?:€|EUR)$/i,
        ""
      );

  const normalized =
    compact.includes(",")
      ? compact
          .replace(/\./g, "")
          .replace(",", ".")
      : compact;

  if (
    !/^\d+(?:\.\d{1,2})?$/.test(
      normalized
    )
  ) {
    throw new Error(
      "Prix illisible : " +
      text
    );
  }

  const amount =
    Number(normalized);

  if (
    !Number.isFinite(amount) ||
    amount < 0
  ) {
    throw new Error(
      "Prix invalide : " +
      text
    );
  }

  return amount;
}


