    return null;
  }

  const number = Number(value);
  return Number.isSafeInteger(number) && number >= 0 ? number : null;
}

function normalizePublicStats(value) {
  const isRecord = item =>
    item !== null && typeof item === "object" && !Array.isArray(item);
  const raw = isRecord(value) ? value : {};
  const readCounters = (group, keys) => Object.fromEntries(
    keys.map(key => [key, optionalCount(isRecord(group) ? group[key] : null)])
  );

  const duration = readCounters(raw.duration, [
    "years", "months", "days", "hours", "minutes"
  ]);
  const parties = readCounters(raw.parties, ["total", "cooperation", "solo"]);
  const details = readCounters(raw.details, ["games", "places", "h_index"]);
  const ready = raw.ready === true &&
    [duration, parties, details].every(group =>
      Object.values(group).every(number => number !== null)
    ) && Array.isArray(raw.top10);

  return {
    ...raw,
    ready,
    reason: ready ? null : String(raw.reason || "Statistiques absentes ou incomplètes"),
    duration,
    parties,
    details,
    top10: Array.isArray(raw.top10) ? raw.top10.filter(isRecord) : []
  };
}

function collectStatsWarnings(existing, publicStats) {
  const warnings = Array.isArray(existing) ? [...existing] : [];
  if (!publicStats.ready) {
    const warning = "Statistiques MyLudo indisponibles ou incomplètes : " + publicStats.reason;
    if (!warnings.includes(warning)) warnings.push(warning);
  }
  return warnings;
}

const publicStats = normalizePublicStats(source.public_stats);
const warnings = collectStatsWarnings(source.warnings, publicStats);

// ============================================================
// HELPERS
// ============================================================

const clean = value =>
  String(value ?? '')
    .replace(/\s+/g, ' ')
    .trim();

const normalize = value =>
  clean(value)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase();

// ============================================================
// CATEGORY NORMALIZATION
// ============================================================

const categoryMap = new Map([
  ['jeu de base', 'Jeux de base'],
  ['jeux de base', 'Jeux de base'],
  ['basegame', 'Jeux de base'],

  ['extension', 'extension'],
  ['standalone', 'standalone'],
  ['accessoire', 'accessoire'],
  ['goodie', 'goodie'],

  ['demo', 'démo'],
  ['démo', 'démo'],

  ['autre', 'autre'],
]);

// ============================================================
// GROUP CREATION
// ============================================================

function createGroup() {
  return {
    categories: {
      'Jeux de base': 0,
      extension: 0,
      standalone: 0,
      accessoire: 0,
      goodie: 0,
      'démo': 0,
      autre: 0,
    },

    genres: new Map(),
    genreLabels: new Map(),

    decades: new Map(),

    total: 0,

    priceCents: 0,
    knownPrices: 0,
    missingPrices: 0,
  };
}

const groups = {
  collection: createGroup(),
  wishlist: createGroup(),
};

// ============================================================
// ANALYZE DATA TABLE ROWS
// ============================================================

for (const row of source.rows) {
  const status = normalize(row.statuts);

  if (!Object.hasOwn(groups, status)) {
    throw new Error(
      `Statut inconnu pour "${row.Nom}" : ${row.statuts}`
    );
  }

  const group = groups[status];

  group.total++;

  // ==========================================================
  // CATEGORY
  // ==========================================================

  const category =
    categoryMap.get(
      normalize(row.categorie)
    ) ?? 'autre';

  group.categories[category]++;

  // ==========================================================
  // GENRES
  // ==========================================================

  const values = Array.isArray(row.genre)
    ? row.genre
    : String(row.genre ?? '').split('|');

  const seen = new Set();

  for (const value of values) {
    const label = clean(value);

    if (!label) {
      continue;
    }

    const key = normalize(label);

    // Count each genre only once per game.
    if (seen.has(key)) {
      continue;
    }

    seen.add(key);

    if (!group.genreLabels.has(key)) {
      group.genreLabels.set(
        key,
        label
      );
    }

    group.genres.set(
      key,
      (group.genres.get(key) ?? 0) + 1
    );
  }

  if (!seen.size) {
    group.genreLabels.set(
      'sans genre',
      'Sans genre'
    );

    group.genres.set(
      'sans genre',
      (group.genres.get('sans genre') ?? 0) + 1
    );
  }

  // ==========================================================
  // PRICE
  // ==========================================================

  const missingPrice =
    row.prix === null ||
    row.prix === undefined ||
    clean(row.prix) === '';

  if (missingPrice) {
    group.missingPrices++;
  } else {
    const price = Number(row.prix);
    const cents = Math.round(price * 100);

    if (
      !Number.isFinite(price) ||
      price < 0 ||
      !Number.isSafeInteger(cents)
    ) {
      throw new Error(
        `Prix invalide pour "${row.Nom}" : ${row.prix}`
      );
    }

    group.priceCents += cents;

    if (!Number.isSafeInteger(group.priceCents)) {
      throw new Error(
        'Total des prix trop grand'
      );
    }

    group.knownPrices++;
  }

  // ==========================================================
  // RELEASE DECADE
  // ==========================================================

  let decade = 'Sans année';

  const missingYear =
    row.annee_sortie === null ||
    row.annee_sortie === undefined ||
    clean(row.annee_sortie) === '';

  if (!missingYear) {
    const year = Number(
      row.annee_sortie
    );

    if (
      !Number.isInteger(year) ||
      year < 1000 ||
      year > 2999
    ) {
      throw new Error(
        `Année invalide pour "${row.Nom}" : ${row.annee_sortie}`
      );
    }

    decade = String(
      Math.floor(year / 10) * 10
    );
  }

  group.decades.set(
    decade,
    (group.decades.get(decade) ?? 0) + 1
  );
}

// ============================================================
// PRICE FORMAT
// ============================================================

const currency = new Intl.NumberFormat(
  'fr-FR',
  {
    style: 'currency',
    currency: 'EUR',
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  }
);

// ============================================================
// FORMAT COLLECTION / WISHLIST
// ============================================================

function formatGroup(group) {
  const genres = [...group.genres]
    .map(([key, count]) => [
      group.genreLabels.get(key),
      count,
    ])
    .sort(
      (a, b) =>
        b[1] - a[1] ||
        a[0].localeCompare(
          b[0],
          'fr'
        )
    );

  const decades = [
    ...group.decades.entries(),
  ].sort((a, b) => {
    if (a[0] === 'Sans année') {
      return 1;
    }

    if (b[0] === 'Sans année') {
      return -1;
    }

    return Number(b[0]) - Number(a[0]);
  });

  const formattedPrice =
    group.knownPrices > 0 ||
    group.total === 0
      ? currency
          .format(
            group.priceCents / 100
          )
          .replace(
            /[\u00a0\u202f]/g,
            ' '
          )
      : null;

  return {
    Total: group.total,

    ...group.categories,

    genre:
      Object.fromEntries(genres),

    prix:
      formattedPrice,

    sans_prix:
      group.missingPrices,

    prix_connus:
      group.knownPrices,

    'décennie':
      Object.fromEntries(decades),
  };
}

// ============================================================
// TOTAL PLAY TIME
// ============================================================

function formatDuration(duration) {
  // A partial duration cannot be presented as a known total.
  const keys = ["years", "months", "days", "hours", "minutes"];
  if (!duration || keys.some(key => optionalCount(duration[key]) === null)) {
    return null;
  }

  const parts = [];

  const years =
    Number(duration.years) || 0;

  const months =
    Number(duration.months) || 0;

  const days =
    Number(duration.days) || 0;

  const hours =
    Number(duration.hours) || 0;

  const minutes =
    Number(duration.minutes) || 0;

  if (years > 0) {
    parts.push(
      `${years} ${
        years === 1
          ? 'an'
          : 'ans'
      }`
    );
  }

  if (months > 0) {
    parts.push(
      `${months} mois`
    );
  }

  if (days > 0) {
    parts.push(
      `${days} j`
    );
  }

  if (hours > 0) {
    parts.push(
      `${hours} h`
    );
  }

  if (
    minutes > 0 ||
    parts.length === 0
  ) {
    parts.push(
      `${minutes} min`
    );
  }

  return parts.join(' ');
}

// ============================================================
// MYLUDO PUBLIC STATISTICS
// ============================================================

const myLudoStats = {
  // ----------------------------------------------------------
  // TOTAL PLAY TIME
  // ----------------------------------------------------------

  duree_totale:
    formatDuration(
      publicStats.duration
    ),

  duree_totale_detail: {
    annees:
      publicStats.duration.years,

    mois:
      publicStats.duration.months,

    jours:
      publicStats.duration.days,

    heures:
      publicStats.duration.hours,

    minutes:
      publicStats.duration.minutes,
  },

  // ----------------------------------------------------------
  // PLAYS
  // ----------------------------------------------------------

  parties: {
    total:
      publicStats.parties.total,

    cooperation:
      publicStats.parties.cooperation,

    solo:
      publicStats.parties.solo,
  },

  // ----------------------------------------------------------
  // DETAILS
  // ----------------------------------------------------------

  details: {
    jeux:
      publicStats.details.games,

    lieux:
      publicStats.details.places,

    h_index:
      publicStats.details.h_index,
  },

  // ----------------------------------------------------------
  // TOP 10 GAMES
  // ----------------------------------------------------------

  top_10:
    publicStats.top10
      .map((entry, index) => ({
        rang:
          Number(entry.rank) ||
          index + 1,

        id:
          entry.id ?? null,

        jeu:
          clean(entry.name) ||
          'Jeu inconnu',

        duree_minutes:
          optionalCount(entry.duration_minutes),

        parties:
          optionalCount(entry.plays),

        url:
          entry.url ?? null,
      }))
      .sort(
        (a, b) =>
          a.rang - b.rang
      ),
};

// ============================================================
// FINAL SINGLE OUTPUT
// ============================================================

return [
  {
    json: {
      Collection:
        formatGroup(
          groups.collection
        ),

      wishlist:
        formatGroup(
          groups.wishlist
        ),

      Statistiques:
        myLudoStats,

      warnings,
    },
  },
];
